:root{font:13px/1.45 -apple-system,BlinkMacSystemFont,"PingFang SC",system-ui,sans-serif;color:#263952;background:#fff;color-scheme:light;--space-1:4px;--space-2:8px;--space-3:12px;--space-4:16px;--radius-control:8px;--radius-surface:12px;--notes-icon-size:34px}
*{box-sizing:border-box}body{margin:0}button,input,textarea{font:inherit}[hidden]{display:none!important}
.notes-app{width:100%;min-width:0;margin:0;padding:var(--space-3)}
