/* Sandboxed tool theme: matching values, not imported host CSS. */
:root{font:13px/1.45 -apple-system,BlinkMacSystemFont,"PingFang SC",system-ui,sans-serif;color:#263952;background:#fff;color-scheme:light;--space-1:4px;--space-2:8px;--space-3:12px;--space-4:16px;--radius-control:8px;--radius-surface:12px;--notes-icon-size:34px}
*{box-sizing:border-box}body{margin:0}button,input,textarea{font:inherit}[hidden]{display:none!important}
.notes-app{width:100%;min-width:0;margin:0;padding:var(--space-3)}
.page-context{display:flex;align-items:flex-start;gap:var(--space-2);min-width:0;padding-bottom:var(--space-3);border-bottom:1px solid #e9edf4}
.notes-mark{display:block;flex:none;width:24px;height:24px;object-fit:contain}
.page-meta{flex:1;min-width:0}.page-summary{font-size:12px;font-weight:600;line-height:1.45;margin:0;overflow-wrap:anywhere}
.page-url{font-size:11px;line-height:1.4;margin:var(--space-1) 0 0;color:#596b83;overflow-wrap:anywhere;word-break:break-word}
.icon-button{position:relative;display:grid;place-items:center;flex:none;width:var(--notes-icon-size);height:var(--notes-icon-size);padding:0;border:1px solid #dfe6f0;background:#fff;border-radius:var(--radius-control);color:#506783;cursor:pointer}
.icon-button svg{width:17px;height:17px;fill:none;stroke:currentColor;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round}
.icon-button:hover:not(:disabled){background:#f1f5fb}.icon-button:disabled{opacity:.4;cursor:default}
.icon-button.primary{background:#365ed3;border-color:#365ed3;color:#fff}.icon-button.primary:hover{background:#2851bf}
.icon-button.danger{color:#a54b52}.icon-button.danger:hover:not(:disabled){background:#fff1f2;border-color:#f1cdd1}
.icon-button:focus-visible::after{content:attr(aria-label);position:absolute;bottom:calc(100% + var(--space-1));right:0;z-index:5;background:#243854;color:#fff;font-size:11px;font-weight:500;white-space:nowrap;border-radius:var(--space-1);padding:var(--space-1) var(--space-2);pointer-events:none;box-shadow:0 2px 8px #15284a28}
:focus-visible{outline:2px solid #365ed3;outline-offset:2px}
.notes-heading{display:flex;align-items:center;gap:var(--space-2);min-height:34px;margin:var(--space-2) 0 var(--space-1)}
.notes-heading label{font-size:13px;font-weight:700;margin:0}.note-count{color:#596b83;font-size:11px}.notes-heading .icon-button{margin-left:auto}
.note-list{display:flex;min-width:0;gap:var(--space-2);overflow-x:auto;padding:0 0 var(--space-2);scrollbar-width:thin}
.note-list:empty{display:none}.note-chip{flex:none;max-width:140px;min-height:32px;padding:var(--space-1) var(--space-2);border:1px solid #e2e8f2;background:#f8faff;border-radius:var(--radius-control);font-size:11px;color:#596b83;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;cursor:pointer}
.note-chip[data-selected="true"]{border-color:#a9bff2;background:#eaf0ff;color:#2e54ac;font-weight:650}.note-chip:hover{background:#eef3ff}
#note-text{display:block;min-width:0;width:100%;min-height:126px;max-height:480px;padding:var(--space-3) var(--space-2);border:1px solid #cad6e7;border-radius:var(--radius-control);resize:vertical;color:#283a52;background:#fff;font-size:13px;line-height:1.55;font-family:inherit;overflow-wrap:anywhere}
#note-text::placeholder{color:#60728a}#note-text:focus-visible{outline:2px solid #365ed3;outline-offset:0;border-color:transparent}
.editor-actions{display:flex;align-items:center;gap:var(--space-2);min-height:34px;margin-top:var(--space-2)}.action-spacer{flex:1}
/* 200% zoom can leave only ~160 CSS px: give the checkbox a complete row,
